  remove() { this.parent.children = this.parent.children.filter(node => node !== this); }
  focus() {}
  all() { return this.children.flatMap(node => [node, ...node.all()]); }
  querySelector() { return this.all().find(node => node.attributes.role === 'alert'); }
}

